package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOutputStream;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOutputStream = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeGNU_File() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);

        String longName = "this_is_a_very_long_filename_that_exceeds_the_standard_tar_limit_of_100_characters_to_trigger_long_link_mode.txt";
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10); // size for the actual entry

        tarOutputStream.putArchiveEntry(entry);

        // Verify state
        // Since we can't easily inspect internal private fields like currName via public API, 
        // we rely on the fact that no exception is thrown and the stream is written to.
        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeGNU_Directory() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);

        String longDirName = "a_very_long_directory_name_that_should_trigger_the_long_link_logic_in_the_tar_stream_format_for_directories";
        TarArchiveEntry entry = new TarArchiveEntry(longDirName);
        // entry.setDirectory() is implicit in constructor or via setter if available, 
        // TarArchiveEntry handles isDirectory via internal flags.

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileModeTruncate() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_TRUNCATE);

        // Name longer than 100 (TarConstants.NAMELEN)
        String longName = "long_name_that_is_longer_than_one_hundred_characters_to_test_the_truncate_mode_logic_branch_in_the_code";
        TarArchiveEntry entry = new TarArchiveEntry(longName);

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_TooLong_ThrowsException() throws IOException {
        // Default mode is usually not LONGFILE_GNU or LONGFILE_TRUNCATE
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX); 

        String longName = "long_name_that_is_longer_than_one_hundred_characters_to_test_the_exception_branch_in_the_code";
        TarArchiveEntry entry = new TarArchiveEntry(longName);

        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_NormalFile() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX);

        String shortName = "short.txt";
        TarArchiveEntry entry = new TarArchiveEntry(shortName);
        entry.setSize(5);

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_NormalDirectory() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveOutputStream.LONGFILE_POSIX);

        String dirName = "short_dir";
        TarArchiveEntry entry = new TarArchiveEntry(dirName);
        // Manually setting directory status if possible, or using constructor logic
        // In TarArchiveEntry, directories are typically identified by the entry type.

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_MockEntry() throws IOException {
        // Using a mock to verify interactions if necessary, though TarArchiveEntry is a data object
        TarArchiveOutputStream spyStream = spy(tarOutputStream);
        TarArchiveEntry mockEntry = mock(TarArchiveEntry.class);

        when(mockEntry.getName()).thenReturn("mock.txt");
        when(mockEntry.isDirectory()).thenReturn(false);
        when(mockEntry.getSize()).thenReturn(10L);

        spyStream.putArchiveEntry(mockEntry);

        verify(mockEntry, times(1)).writeEntryHeader(any());
    }
}
